import{_ as a,r as c,o as r,c as s,e as o,a as t,s as h}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"目录结构 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"根目录","slug":"根目录","link":"#根目录","children":[{"level":3,"title":"引导程序目录","slug":"引导程序目录","link":"#引导程序目录","children":[]},{"level":3,"title":"配置目录","slug":"配置目录","link":"#配置目录","children":[]},{"level":3,"title":"模块目录","slug":"模块目录","link":"#模块目录","children":[]},{"level":3,"title":"插件目录","slug":"插件目录","link":"#插件目录","children":[]},{"level":3,"title":"存储目录","slug":"存储目录","link":"#存储目录","children":[]},{"level":3,"title":"主题目录","slug":"主题目录","link":"#主题目录","children":[]},{"level":3,"title":"供应商目录","slug":"供应商目录","link":"#供应商目录","children":[]}]},{"level":2,"title":"模块目录","slug":"模块目录-1","link":"#模块目录-1","children":[{"level":3,"title":"系统模块","slug":"系统模块","link":"#系统模块","children":[]},{"level":3,"title":"CMS 模块","slug":"cms-模块","link":"#cms-模块","children":[]},{"level":3,"title":"后端模块","slug":"后端模块","link":"#后端模块","children":[]},{"level":3,"title":"编辑器模块","slug":"编辑器模块","link":"#编辑器模块","children":[]},{"level":3,"title":"媒体模块","slug":"媒体模块","link":"#媒体模块","children":[]}]}],"relativePath":"2.x/zh-cn/setup/structure.md","filePath":"2.x/zh-cn/setup/structure.md"}'),i={name:"2.x/zh-cn/setup/structure.md"};function n(p,e,u,m,_,f){const d=c("pre-heading"),l=c("post-heading");return r(),s("div",null,[o(d),e[0]||(e[0]=t("h1",null,"目录结构",-1)),o(l),e[1]||(e[1]=h('<p>有许多不同的活动部件组合在一起使October CMS 平台正常工作。默认情况下，October CMS 使用模块化结构，其中大多数编程功能都可以在模块或插件目录中找到。唯一需要的模块是系统模块。</p><h2 id="根目录"><a href="#根目录" class="header-anchor">#</a> 根目录</h2><h3 id="引导程序目录"><a href="#引导程序目录" class="header-anchor">#</a> 引导程序目录</h3><p><code>bootstrap</code> 目录包含加载 Laravel 框架的 <code>app.php</code> 引导程序文件。该目录还包含应用程序使用的自定义自动加载器，任何需要在应用程序内加载文件的脚本都会将其加载。您通常不需要修改此目录中的任何文件。</p><h3 id="配置目录"><a href="#配置目录" class="header-anchor">#</a> 配置目录</h3><p><code>config</code> 目录包含所有应用程序配置文件。 每个文件控制着应用程序对应的功能，最好熟悉每个文件及其内容。 这些属于您的应用程序，可以根据需要进行修改，系统更新期间不会触及它们</p><h3 id="模块目录"><a href="#模块目录" class="header-anchor">#</a> 模块目录</h3><p><code>modules</code> 目录包含与 October CMS 一起包含的核心包，提供整个系统通用的 <a href="#oc-modules-directory">核心功能</a>。默认情况下，模块会根据它们在文件系统中的存在情况自动加载，但是，您可以使用 <code>system.load_modules</code> 配置项手动指定要加载的模块。必须至少加载系统模块才能使应用程序运行。</p><h3 id="插件目录"><a href="#插件目录" class="header-anchor">#</a> 插件目录</h3><p><code>plugins</code> 目录包含扩展 October CMS 核心功能的包。与模块类似，他们可以通过引入新功能或扩展其他插件来修改平台。插件在文件系统中找到时会自动加载，但是，您可以使用 <code>system.disable_plugins</code> 配置项手动禁用插件。</p><h3 id="存储目录"><a href="#存储目录" class="header-anchor">#</a> 存储目录</h3><p><code>storage</code> 目录包含了由 October CMS 生成的日志文件、缓存文件、会话和其他文件。内部目录被分为 <code>app</code> 、 <code>cms</code> 、 <code>framework</code> 、 <code>logs</code> 和 <code>temp</code> 。</p><p><code>app</code> 存储目录包含特定于应用程序的存储项目，例如媒体文件、文件上传和自动生成的资源，例如调整大小的文件和组合资产文件。 Laravel 框架使用<code>framework</code> 存储目录来存储其生成的文件和缓存。 <code>cms</code> 存储目录被October CMS 平台用于存储其生成的文件和缓存。 <code>logs</code> 存储目录包含您的应用程序的日志文件。 <code>temp</code> 存储目录是应用程序使用的工作目录。</p><h3 id="主题目录"><a href="#主题目录" class="header-anchor">#</a> 主题目录</h3><p><code>themes</code> 目录包含用于管理网站前端结构的静态文件内容。使用 <code>cms.active_theme</code> 配置项设置活动主题。</p><h3 id="供应商目录"><a href="#供应商目录" class="header-anchor">#</a> 供应商目录</h3><p><code>vendor</code> 目录包含项目的Composer包，有时也可以在特定于插件的 <code>/vendor</code> 目录中找到。 项目供应商目录优先于系统中出现的插件供应商目录。</p><p><a id="oc-modules-directory"></a></p><h2 id="模块目录-1"><a href="#模块目录-1" class="header-anchor">#</a> 模块目录</h2><h3 id="系统模块"><a href="#系统模块" class="header-anchor">#</a> 系统模块</h3><p><code>system</code> 模块包含October CMS 的核心功能，是必需的模块。它具有其他模块使用的共享逻辑。</p><h3 id="cms-模块"><a href="#cms-模块" class="header-anchor">#</a> CMS 模块</h3><p><code>cms</code> 模块引入了渲染前端页面和加载主题的功能。它负责路由到页面、呈现部件和处理 AJAX 请求。</p><h3 id="后端模块"><a href="#后端模块" class="header-anchor">#</a> 后端模块</h3><p><code>backend</code> 模块负责呈现后端页面并编排菜单、布局和其他管理功能。</p><h3 id="编辑器模块"><a href="#编辑器模块" class="header-anchor">#</a> 编辑器模块</h3><p><code>editor</code> 模块将代码编辑器引入到 October CMS 的后端界面。它允许您直接在后端管理网站主题。</p><h3 id="媒体模块"><a href="#媒体模块" class="header-anchor">#</a> 媒体模块</h3><p><code>media</code> 模块为 October CMS 的后端界面引入了媒体管理功能。它允许您上传媒体文件以包含在其他区域。</p>',29))])}const k=a(i,[["render",n]]);export{v as __pageData,k as default};
